/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-04: single-flow api v2 - rev and ETag in GET, If-Match in PUT, 201 for a created
 *   flow (POST, PUT with deploy.putCreatesFlow), revisions in the response
 *   Z-05: DELETE passes ?rev= to the runtime
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

var runtimeAPI;
var apiUtils = require("../util");

// The requested API version, or null (after a 400 response) if it is invalid
function getApiVersion(req, res) {
    var version = req.get("Node-RED-API-Version")||"v1";
    if (!/^v[12]$/.test(version)) {
        res.status(400).json({code:"invalid_api_version", message:"Invalid API Version requested"});
        return null;
    }
    return version;
}

// The revision in an If-Match header (quotes and a weak prefix removed); "*"
// and an empty header mean no revision
function getIfMatch(req) {
    var value = req.get("If-Match");
    if (!value) {
        return undefined;
    }
    value = value.trim().replace(/^W\//, "").replace(/^"(.*)"$/, "$1");
    if (value === "" || value === "*") {
        return undefined;
    }
    return value;
}

module.exports = {
    init: function(_runtimeAPI) {
        runtimeAPI = _runtimeAPI;
    },
    get: function(req,res) {
        var version = getApiVersion(req,res);
        if (!version) {
            return;
        }
        var opts = {
            user: req.user,
            id: req.params.id,
            apiVersion: version,
            req: apiUtils.getRequestLogObject(req)
        }
        runtimeAPI.flows.getFlow(opts).then(function(result) {
            if (version === "v2" && result && result.rev) {
                // Z-04 (R-13): the revision of the flow as the entity tag
                res.set("ETag", '"'+result.rev+'"');
            }
            return res.json(result);
        }).catch(function(err) {
            apiUtils.rejectHandler(req,res,err);
        })
    },
    post: function(req,res) {
        var version = getApiVersion(req,res);
        if (!version) {
            return;
        }
        var opts = {
            user: req.user,
            flow: req.body,
            apiVersion: version,
            req: apiUtils.getRequestLogObject(req)
        }
        runtimeAPI.flows.addFlow(opts).then(function(result) {
            if (version === "v2") {
                // Z-04 (R-13, R-34): 201 with the id and revision of the new flow
                return res.status(201).json(result);
            }
            return res.json({id:result});
        }).catch(function(err) {
            apiUtils.rejectHandler(req,res,err);
        })
    },
    put: function(req,res) {
        var version = getApiVersion(req,res);
        if (!version) {
            return;
        }
        var flow = req.body;
        if (version === "v2") {
            // Z-04 (R-34, R-43): If-Match is equivalent to rev; both given and
            // different - 400 invalid_revision. Ignored in v1.
            var ifMatch = getIfMatch(req);
            if (ifMatch !== undefined) {
                if (flow && typeof flow === "object" && flow.hasOwnProperty("rev")) {
                    if (flow.rev !== ifMatch) {
                        return res.status(400).json({code:"invalid_revision", message:"If-Match and rev differ"});
                    }
                } else {
                    flow = Object.assign({}, flow, {rev: ifMatch});
                }
            }
        }
        var opts = {
            user: req.user,
            id: req.params.id,
            flow: flow,
            apiVersion: version,
            req: apiUtils.getRequestLogObject(req)
        }
        runtimeAPI.flows.updateFlow(opts).then(function(result) {
            if (version === "v2") {
                // Z-04 (R-34): 201 when the flow was created (deploy.putCreatesFlow)
                return res.status(result.created ? 201 : 200).json({id:result.id, rev:result.rev, revAll:result.revAll});
            }
            return res.json({id:result});
        }).catch(function(err) {
            apiUtils.rejectHandler(req,res,err);
        })
    },
    delete: function(req,res) {
        var opts = {
            user: req.user,
            id: req.params.id,
            req: apiUtils.getRequestLogObject(req)
        }
        if (req.query && typeof req.query.rev === "string") {
            // Z-05 (R-14): the revision of the flow to delete
            opts.rev = req.query.rev;
        }
        runtimeAPI.flows.deleteFlow(opts).then(function() {
            res.status(204).end();
        }).catch(function(err) {
            apiUtils.rejectHandler(req,res,err);
        })
    }
}
